const rawUrl = String($json.canonical_url ?? '').trim();
const selector = String($json.content_selector ?? '').trim();
const allowedHosts = Array.isArray($json.allowed_hosts)
  ? $json.allowed_hosts.map((host) => String(host).toLowerCase())
  : [];

if (!Number.isInteger(Number($json.article_id)) || rawUrl.length > 4000) {
  throw new Error('The claimed article metadata is invalid.');
}

const match = rawUrl.match(/^https:\/\/([^\/?#:@]+)(?::(\d+))?(?:[\/?#]|$)/i);
if (!match) {
  throw new Error('The claimed article URL is not a safe HTTPS URL.');
}

const hostname = match[1].toLowerCase();
const port = match[2] ?? '';
if ((port && port !== '443') || !allowedHosts.includes(hostname)) {
  throw new Error('The claimed article URL failed its reviewed host allowlist.');
}

if (!selector || selector.length > 200 || !/^[a-zA-Z0-9_#.*\[\]=\"'():,>+~ -]+$/.test(selector)) {
  throw new Error('The reviewed content selector is invalid.');
}

return {
  json: {
    ...$json,
    canonical_url: rawUrl,
    content_selector: selector,
  },
};

const claimed = $('Claim One Analysis Job').item.json;
let content = String($json.content ?? '');

content = content
  .replace(/data:image\/[a-z0-9.+-]+;base64,[a-z0-9+/=\s]+/gi, ' ')
  .replace(/https?:\/\/\S+/gi, ' ')
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

if (content.length < 300) {
  throw new Error('The extracted article content is too short.');
}

content = content.slice(0, 16000);

return {
  json: {
    article_id: claimed.article_id,
    canonical_url: claimed.canonical_url,
    title: claimed.title,
    source_name: claimed.source_name,
    source_trust_score: Math.max(0, Math.min(100, Number(claimed.source_trust_score) || 0)),
    cleaned_content: content,
  },
};

const article = $json;
const title = String(article.title ?? '').replace(/\s+/g, ' ').trim();
const content = String(article.cleaned_content ?? '').replace(/\s+/g, ' ').trim();
const sourceTrust = Math.max(0, Math.min(100, Number(article.source_trust_score) || 0));
const text = `${title} ${content}`;
const lower = text.toLowerCase();

const cves = [...new Set((text.match(/\bCVE-\d{4}-\d{4,}\b/gi) ?? []).map((value) => value.toUpperCase()))]
  .sort()
  .slice(0, 50);

const cvssScores = [];
const cvssPatterns = [
  /\bcvss(?:\s+v?\d(?:\.\d)?)?\s+(?:base\s+)?score\s*(?:of|is|:|=)?\s*(10(?:\.0)?|[0-9](?:\.[0-9])?)/gi,
  /\bcvss(?:\s+v?\d(?:\.\d)?)?\s*[:=]\s*(10(?:\.0)?|[0-9](?:\.[0-9])?)/gi,
];
for (const pattern of cvssPatterns) {
  for (const match of text.matchAll(pattern)) {
    const score = Number(match[1]);
    if (Number.isFinite(score) && score >= 0 && score <= 10) cvssScores.push(score);
  }
}
const cvssMax = cvssScores.length ? Math.max(...cvssScores) : null;

const hasActiveExploitation = /\b(actively exploited|active exploitation|exploited in the wild|known exploited|under active exploitation|evidence of active exploitation)\b/i.test(text);
const hasPatch = /\b(patch(?:es)? available|security update(?:s)? available|fixed in|released (?:a |the )?patch|mitigation(?:s)? available|upgrade to|apply (?:the )?(?:latest )?(?:patch|update))\b/i.test(text);
const hasPoc = /\b(proof[- ]of[- ]concept|poc exploit|public exploit|exploit code (?:is )?(?:available|released|published))\b/i.test(text);

const scores = { malware: 0, vulnerability: 0, data_breach: 0, threat_intelligence: 0 };
if (cves.length) scores.vulnerability += 4;
if (cvssMax !== null) scores.vulnerability += 3;
if (/\b(vulnerabilit(?:y|ies)|security flaw|zero[- ]day|remote code execution|rce|privilege escalation|authentication bypass)\b/i.test(text)) scores.vulnerability += 3;
if (/\b(malware|ransomware|trojan|backdoor|botnet|infostealer|information stealer|loader malware|remote access trojan|banking trojan|rootkit)\b/i.test(text)) scores.malware += 4;
if (/\b(data breach|breached|data leak|leaked records|exposed records|stolen data|customer data exposed|database exposed)\b/i.test(text)) scores.data_breach += 4;
if (/\b(threat actor|apt[- ]?\d*|advanced persistent threat|espionage campaign|malicious campaign|indicators? of compromise|\biocs?\b|threat intelligence)\b/i.test(text)) scores.threat_intelligence += 3;
if (/\b(campaign|targeted attacks?|nation[- ]state|state[- ]sponsored)\b/i.test(text)) scores.threat_intelligence += 1;

const ranked = Object.entries(scores).sort((left, right) => right[1] - left[1]);
const bestScore = ranked[0][1];
const margin = bestScore - ranked[1][1];
const category = bestScore > 0 ? ranked[0][0] : 'other';

let severity = 'unknown';
if (cvssMax !== null) {
  severity = cvssMax >= 9 ? 'critical' : cvssMax >= 7 ? 'high' : cvssMax >= 4 ? 'medium' : 'low';
} else if (/\bcritical(?:ly)?\b/i.test(text) && /\b(remote code execution|rce|unauthenticated|wormable)\b/i.test(text)) {
  severity = 'critical';
} else if (hasActiveExploitation || /\b(ransomware|high severity|high-severity)\b/i.test(text)) {
  severity = 'high';
} else if (/\b(medium severity|moderate severity|medium-severity)\b/i.test(text)) {
  severity = 'medium';
} else if (/\b(low severity|low-severity)\b/i.test(text)) {
  severity = 'low';
}

const sentenceCandidates = content.match(/[^.!?]+[.!?]+|[^.!?]+$/g) ?? [];
let ruleSummary = sentenceCandidates.slice(0, 2).map((value) => value.trim()).filter(Boolean).join(' ');
if (ruleSummary.length < 20) ruleSummary = `${title}. ${content.slice(0, 900)}`.trim();
ruleSummary = ruleSummary.slice(0, 1200).trim();
if (ruleSummary.length < 20) throw new Error('Unable to build a safe deterministic summary.');

const reasons = [];
if (cves.length) reasons.push('cve_detected');
if (cvssMax !== null) reasons.push('cvss_detected');
if (hasActiveExploitation) reasons.push('active_exploitation');
if (hasPatch) reasons.push('patch_available');
if (hasPoc) reasons.push('poc_available');
if (sourceTrust >= 90) reasons.push('high_trust_source');
if (category !== 'other') reasons.push(`category_signal_${category}`);
if (margin < 2 && category !== 'other') reasons.push('category_overlap');
if (category === 'other') reasons.push('ambiguous_category');

let confidence = category === 'other' ? 0.45 : 0.55;
if (cves.length) confidence += 0.18;
if (cvssMax !== null) confidence += 0.08;
if (sourceTrust >= 90) confidence += 0.08;
if (margin >= 2) confidence += 0.08;
if (hasActiveExploitation) confidence += 0.05;
confidence = Math.min(0.99, Number(confidence.toFixed(3)));

let priority = Math.round(sourceTrust * 0.25);
if (cves.length) priority += 15;
if (cvssMax !== null) priority += Math.round(cvssMax * 3);
if (hasActiveExploitation) priority += 30;
if (hasPoc) priority += 10;
if (category === 'malware' || category === 'data_breach') priority += 12;
priority = Math.max(0, Math.min(100, priority));

const aiRecommendation = confidence >= 0.9 && sourceTrust >= 80 && category !== 'other'
  ? 'candidate_bypass'
  : 'required';
const triage = {
  ruleset_version: 'cti-rules-v1',
  cves,
  cvss_max: cvssMax,
  has_active_exploitation: hasActiveExploitation,
  has_patch: hasPatch,
  has_poc: hasPoc,
  detected_category: category,
  detected_severity: severity,
  rule_summary: ruleSummary,
  rule_confidence: confidence,
  priority_score: priority,
  source_trust_score: sourceTrust,
  ai_recommendation: aiRecommendation,
  decision_reasons: reasons.slice(0, 20),
};

return { json: { ...article, ...triage, triage_payload: JSON.stringify(triage) } };

