const article = $('Sanitize Article Text').item.json;
const candidate = Array.isArray($json?.candidates) ? $json.candidates[0] : $json;
const raw = candidate?.content?.parts?.[0]?.text;
if (typeof raw !== 'string' || raw.length > 6000) {
  throw new Error('Gemini returned an invalid payload shape.');
}

const normalized = raw
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();
const parsed = JSON.parse(normalized);
const categories = new Set(['malware', 'vulnerability', 'data_breach', 'threat_intelligence', 'other']);
const severities = new Set(['critical', 'high', 'medium', 'low', 'unknown']);
const category = String(parsed.category ?? '').trim().toLowerCase();
const severity = String(parsed.severity ?? '').trim().toLowerCase();
const summary = String(parsed.summary_tr ?? '').replace(/\s+/g, ' ').trim();
const confidence = Number(parsed.confidence);

if (!categories.has(category) || !severities.has(severity)) {
  throw new Error('Gemini returned an unsupported classification.');
}
if (summary.length < 20 || summary.length > 1500) {
  throw new Error('Gemini returned an invalid summary length.');
}
if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) {
  throw new Error('Gemini returned an invalid confidence score.');
}

const usage = $json.usageMetadata ?? {};
return {
  json: {
    article_id: article.article_id,
    category,
    severity,
    summary_tr: summary,
    cleaned_content: article.cleaned_content,
    confidence,
    model: 'models/gemini-3.6-flash',
    prompt_tokens: Math.max(0, Number(usage.promptTokenCount ?? 0) || 0),
    output_tokens: Math.max(0, Number(usage.candidatesTokenCount ?? 0) || 0),
  },
};
